script:
(function () {
  window.hrOpsRoute = function (doctype) {
    frappe.route_options = null;
    frappe.set_route('List', doctype);
  };

  window.hrOpsOpenLeaveQueue = function () {
    frappe.route_options = {
      status: ['in', ['Pending HR Approval', 'Pending HR Verification', 'Pending Leave Adjustment HR Review']],
    };
    frappe.set_route('List', 'Leave Application');
  };

  window.hrOpsOpenPendingHRApproval = function () {
    frappe.route_options = { status: 'Pending HR Manager Approval' };
    frappe.set_route('List', 'Leave Application');
  };

  window.hrOpsOpenPayrollDraft = function () {
    frappe.route_options = { docstatus: 0 };
    frappe.set_route('List', 'Payroll Entry');
  };

  async function refreshCounts() {
    try {
      const leaveQueue = await frappe.db.count('Leave Application', {
        filters: {
          status: ['in', ['Pending HR Approval', 'Pending HR Verification', 'Pending Leave Adjustment HR Review']],
        },
      });
      const pendingHr = await frappe.db.count('Leave Application', {
        filters: { status: 'Pending HR Manager Approval' },
      });
      const payrollDraft = await frappe.db.count('Payroll Entry', {
        filters: { docstatus: 0 },
      });

      const q = document.getElementById('hr_ops_count_leave_queue');
      const p = document.getElementById('hr_ops_count_pending_hr');
      const d = document.getElementById('hr_ops_count_payroll_draft');
      if (q) q.textContent = String(leaveQueue || 0);
      if (p) p.textContent = String(pendingHr || 0);
      if (d) d.textContent = String(payrollDraft || 0) + ' draft';
    } catch (e) {
      // Keep defaults if counts fail.
    }
  }

  refreshCounts();
})();

