script:
(function () {
  const root = (typeof root_element !== 'undefined' && root_element) ? root_element : document;

  function blendOuterWidgetChrome() {
    try {
      const host = root && root.host;
      const widget = host && host.closest ? host.closest('.widget') : null;
      const widgetBody = host && host.closest ? host.closest('.widget-body') : null;
      const widgetGroup = host && host.closest ? host.closest('.widget-group') : null;
      [widget, widgetBody, widgetGroup].forEach((el) => {
        if (!el) return;
        el.style.background = 'transparent';
        el.style.border = '0';
        el.style.boxShadow = 'none';
      });
    } catch (e) {}
  }

  const firstNameEl = root.querySelector('#home-mockup-firstname');
  if (!firstNameEl) return;

  const fallbackName = 'User';

  function setName(name) {
    const cleaned = (name || '').trim();
    firstNameEl.textContent = cleaned || fallbackName;
  }

  function firstFromFullName(fullName) {
    return (fullName || '').trim().split(/\s+/)[0] || '';
  }

  async function resolveName() {
    blendOuterWidgetChrome();
    try {
      const sessionUser = frappe.session && frappe.session.user;
      const bootUser = frappe.boot && frappe.boot.user_info && sessionUser ? frappe.boot.user_info[sessionUser] : null;
      if (bootUser) {
        if (bootUser.first_name) return setName(bootUser.first_name);
        if (bootUser.full_name) return setName(firstFromFullName(bootUser.full_name));
      }
      if (frappe.session && frappe.session.user_fullname) {
        const name = firstFromFullName(frappe.session.user_fullname);
        if (name) return setName(name);
      }
      if (sessionUser) {
        const r = await frappe.call({
          method: 'frappe.client.get_value',
          args: {
            doctype: 'User',
            filters: { name: sessionUser },
            fieldname: ['first_name', 'full_name']
          }
        });
        const msg = r && r.message;
        if (msg) {
          const firstName = (msg.first_name || '').trim();
          if (firstName) return setName(firstName);
          const fromFull = firstFromFullName(msg.full_name || '');
          if (fromFull) return setName(fromFull);
        }
        const fromEmail = sessionUser.split('@')[0];
        if (fromEmail) return setName(fromEmail);
      }
      setName(fallbackName);
    } catch (e) {
      setName(fallbackName);
    }
  }

  resolveName();
})();

